sys_script_include.script:
var IFirewallAdapter = Class.create();
IFirewallAdapter.prototype = {
    fetchObjects: function(schemaKey) {
        throw "fetchObjects() must be implemented by subclass.";
    },

	pushObject: function(objectData) {
        throw "pushObject() must be implemented by subclass.";
    },

	editObject: function(objectData) {
		throw "editObject() must be implemented by sublcass.";
	},

    deleteObject: function(objectId) {
        throw "deleteObject() must be implemented by subclass.";
    },

    getCommitJob: function(jobId) {
        throw "getCommitJob() must be implemented by subclass.";
    },

    commitToFirewall: function() {
        throw "commitToFirewall() must be implemented by subclass.";
    },

    type: 'IFirewallAdapter'
};
